mapper.insert:
INSERT INTO model_provider (
type, name, description, api_key, base_url, status, is_public, creator, active, create_time, update_time
) VALUES (
#{type}, #{name}, #{description}, #{apiKey}, #{baseUrl}, #{status}, #{isPublic}, #{creator}, #{active}, #{createTime},
#{updateTime}
)

mapper.select:
SELECT * FROM model_provider
WHERE active = 1
AND (is_public = 1 OR creator = #{currentUsername})

    AND (name LIKE CONCAT('%', #{name}, '%') OR description LIKE CONCAT('%', #{name}, '%'))


    AND type = #{type}


    AND status = #{status}


    AND is_public = #{isPublic}

ORDER BY status DESC, update_time DESC
